function spawnKeys () {
    for (let location of tiles.getTilesByType(assets.tile`marker`)) {
        tiles.setTileAt(location, assets.tile`floorDark0`)
        tiles.placeOnTile(sprites.create(assets.image`key2`, SpriteKind.Key), tiles.getTileLocation(location.column, location.row))
    }
}
