scene.onHitWall(SpriteKind.Player, function (sprite, location) {
    for (let doorLocation of doors) {
        if (doorLocation.column == location.column && doorLocation.row == location.row) {
            if (keyInventory.length >= 1) {
                tiles.setTileAt(doorLocation, assets.tile`floorDark0`)
                tiles.setTileAt(tiles.getTileLocation(doorLocation.column, doorLocation.row - 1), assets.tile`floorDark0`)
                tiles.setTileAt(tiles.getTileLocation(doorLocation.column, doorLocation.row + 1), assets.tile`floorDark0`)
                tiles.setWallAt(doorLocation, false)
                tiles.setWallAt(tiles.getTileLocation(doorLocation.column, doorLocation.row - 1), false)
                tiles.setWallAt(tiles.getTileLocation(doorLocation.column, doorLocation.row + 1), false)
                sprites.destroy(keyInventory.pop())
            } else {
                game.showLongText("oops, you have no key", DialogLayout.Bottom)
            }
            break;
        }
    }
})
