scene.onOverlapTile(SpriteKind.Player, sprites.dungeon.floorDarkDiamond, function (sprite, location) {
    music.stopAllSounds()
    music.play(pianoRoll.createSong(assets.song`bossFight`), music.PlaybackMode.LoopingInBackground)
    tiles.setTileAt(location, sprites.dungeon.floorDark0)
    activateWitch()
    game.showLongText("It's time to face the pumpkin witch.", DialogLayout.Bottom)
    game.showLongText("Don't let it catches you!", DialogLayout.Bottom)
})
function changePumpkinScoreBy (num: number) {
    pumpkinCount += num
    fancyText.setText(pumpkinCountText, "x" + pumpkinCount)
    if (pumpkinCount >= 5) {
        fancyText.setColor(pumpkinCountText, 2)
    } else {
        fancyText.setColor(pumpkinCountText, 1)
    }
}
