function createDecosAtRandom (count: number, decoSpriteImage: Image, tile: number) {
    for (let index = 0; index < count; index++) {
        newDeco = sprites.create(decoSpriteImage, SpriteKind.Deco)
        if (tile == 1) {
            tiles.placeOnRandomTile(newDeco, sprites.dungeon.floorDark0)
        }
        if (tile == 2) {
            tiles.placeOnRandomTile(newDeco, sprites.castle.tilePath5)
        }
    }
}
sprites.onOverlap(SpriteKind.Projectile, SpriteKind.Enemy, function (sprite, otherSprite) {
    music.play(music.melodyPlayable(music.thump), music.PlaybackMode.InBackground)
    sprites.destroy(otherSprite, effects.ashes, 200)
    sprites.destroy(sprite)
    info.changeScoreBy(1)
    scorec += 1
    if (Math.percentChance(50)) {
        pumpkin = sprites.create(assets.image`pumpkinIcon`, SpriteKind.Food)
        tiles.placeOnTile(pumpkin, otherSprite.tilemapLocation())
    }
})
sprites.onOverlap(SpriteKind.Player, SpriteKind.Enemy, function (sprite, otherSprite) {
    music.play(music.melodyPlayable(music.bigCrash), music.PlaybackMode.InBackground)
    scene.cameraShake(4, 500)
    sprites.destroy(otherSprite)
    zoeyHealth.value += -20
})
function activateWitch () {
    witch = sprites.create(assets.image`witch_100`, SpriteKind.Boss)
    tiles.placeOnTile(witch, tiles.getTileLocation(3, 3))
    bossHealth = statusbars.create(30, 3, StatusBarKind.EnemyHealth)
    bossHealth.attachToSprite(witch, 2, 0)
    bossHealth.setColor(4, 13)
    bossLevel = true
    witch.follow(zoey, 20)
    witch.setBounceOnWall(true)
}
